import { Router, type Request, type Response } from 'express';

export interface CreateBookmarkInput {
  url: string;
  title?: string;
  tags?: string[];
}

function isCreateBookmarkInput(body: unknown): body is CreateBookmarkInput {
  if (typeof body !== 'object' || body === null) {
    return false;
  }
  const candidate = body as Record<string, unknown>;
  if (typeof candidate.url !== 'string') {
    return false;
  }
  if (candidate.title !== undefined && typeof candidate.title !== 'string') {
    return false;
  }
  if (candidate.tags !== undefined) {
    if (!Array.isArray(candidate.tags)) {
      return false;
    }
    for (const tag of candidate.tags) {
      if (typeof tag !== 'string') {
        return false;
      }
    }
  }
  return true;
}

export const bookmarksRouter = Router();

bookmarksRouter.post('/', (req: Request, res: Response) => {
  const body: unknown = req.body;
  if (!isCreateBookmarkInput(body)) {
    res.status(400).json({ error: 'Invalid bookmark payload' });
    return;
  }

  const { url, title, tags } = body;
  res.status(201).json({
    url,
    title,
    tags,
  });
});

export default bookmarksRouter;

import { Router, type Request, type Response } from 'express';
import { z } from 'zod';

export const createBookmarkSchema = z.object({
  url: z.string().url().max(2048),
  title: z.string().max(200).optional(),
  tags: z.array(z.string().max(50)).max(10).optional(),
});

export type CreateBookmarkInput = z.infer<typeof createBookmarkSchema>;

export const bookmarksRouter = Router();

bookmarksRouter.post('/', (req: Request, res: Response) => {
  const body: unknown = req.body;
  const parseResult = createBookmarkSchema.safeParse(body);

  if (!parseResult.success) {
    res.status(422).json({
      error: 'Validation failed',
      details: parseResult.error.errors,
    });
    return;
  }

  const { url, title, tags } = parseResult.data;
  res.status(201).json({
    url,
    title,
    tags,
  });
});

export default bookmarksRouter;

