import { describe, it, expect } from 'vitest';
import { createBookmarkSchema } from './bookmarks.js';

describe('createBookmarkSchema', () => {
  it('should validate valid inputs with all fields provided', () => {
    const input: unknown = {
      url: 'https://example.com',
      title: 'Example Domain',
      tags: ['web', 'example'],
    };

    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(true);
    if (result.success) {
      expect(result.data.url).toBe('https://example.com');
      expect(result.data.title).toBe('Example Domain');
      expect(result.data.tags).toEqual(['web', 'example']);
    }
  });

  it('should validate valid inputs with only required url', () => {
    const input: unknown = {
      url: 'https://example.com/docs',
    };

    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(true);
    if (result.success) {
      expect(result.data.url).toBe('https://example.com/docs');
      expect(result.data.title).toBeUndefined();
      expect(result.data.tags).toBeUndefined();
    }
  });

  it('should reject when url is missing', () => {
    const input: unknown = {
      title: 'Missing URL',
      tags: ['test'],
    };

    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
    if (!result.success) {
      const urlIssue = result.error.issues.find((issue) => issue.path.includes('url'));
      expect(urlIssue).toBeDefined();
    }
  });

  it('should reject when url is invalid', () => {
    const input: unknown = {
      url: 'not-a-valid-url',
    };

    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
    if (!result.success) {
      const urlIssue = result.error.issues.find((issue) => issue.path.includes('url'));
      expect(urlIssue).toBeDefined();
    }
  });

  it('should reject when url is too long (> 2048 characters)', () => {
    const longPath = 'a'.repeat(2050);
    const input: unknown = {
      url: `https://example.com/${longPath}`,
    };

    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
    if (!result.success) {
      const urlIssue = result.error.issues.find((issue) => issue.path.includes('url'));
      expect(urlIssue).toBeDefined();
    }
  });

  it('should reject when title is too long (> 200 characters)', () => {
    const input: unknown = {
      url: 'https://example.com',
      title: 'a'.repeat(201),
    };

    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
    if (!result.success) {
      const titleIssue = result.error.issues.find((issue) => issue.path.includes('title'));
      expect(titleIssue).toBeDefined();
    }
  });

  it('should reject when there are too many tags (> 10 tags)', () => {
    const input: unknown = {
      url: 'https://example.com',
      tags: Array.from({ length: 11 }, (_, i) => `tag-${i}`),
    };

    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
    if (!result.success) {
      const tagIssue = result.error.issues.find((issue) => issue.path.includes('tags'));
      expect(tagIssue).toBeDefined();
    }
  });

  it('should reject when any tag is too long (> 50 characters)', () => {
    const input: unknown = {
      url: 'https://example.com',
      tags: ['valid-tag', 'a'.repeat(51)],
    };

    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
    if (!result.success) {
      const tagIssue = result.error.issues.find((issue) => issue.path.includes('tags'));
      expect(tagIssue).toBeDefined();
    }
  });
});

