import { describe, it, expect, beforeEach } from 'vitest';
import { BookmarkService, DuplicateBookmarkError } from './bookmark-service.js';

describe('BookmarkService', () => {
  let service: BookmarkService;

  beforeEach(() => {
    service = new BookmarkService();
  });

  describe('create', () => {
    it('should successfully create a bookmark with all fields', () => {
      const input = {
        url: 'https://example.com',
        title: 'Example Domain',
        tags: ['example', 'web'],
      };

      const bookmark = service.create(input);

      expect(bookmark.id).toBeDefined();
      expect(typeof bookmark.id).toBe('string');
      expect(bookmark.url).toBe('https://example.com');
      expect(bookmark.title).toBe('Example Domain');
      expect(bookmark.tags).toEqual(['example', 'web']);
      expect(bookmark.createdAt).toBeDefined();
      expect(new Date(bookmark.createdAt).toISOString()).toBe(bookmark.createdAt);
    });

    it('should default tags to an empty array if not provided', () => {
      const bookmark = service.create({
        url: 'https://example.com/no-tags',
      });

      expect(bookmark.tags).toEqual([]);
      expect(bookmark.title).toBeUndefined();
    });

    it('should generate unique IDs for each created bookmark', () => {
      const b1 = service.create({ url: 'https://example.com/1' });
      const b2 = service.create({ url: 'https://example.com/2' });

      expect(b1.id).not.toBe(b2.id);
    });
  });

  describe('duplicate detection', () => {
    it('should throw DuplicateBookmarkError when creating a bookmark with an existing URL', () => {
      service.create({ url: 'https://example.com' });

      expect(() => {
        service.create({ url: 'https://example.com' });
      }).toThrow(DuplicateBookmarkError);
    });

    it('should include the conflicting URL in the DuplicateBookmarkError message', () => {
      const targetUrl = 'https://example.com/duplicate';
      service.create({ url: targetUrl });

      try {
        service.create({ url: targetUrl });
        expect.unreachable('Should have thrown DuplicateBookmarkError');
      } catch (error: unknown) {
        expect(error instanceof DuplicateBookmarkError).toBe(true);
        if (error instanceof DuplicateBookmarkError) {
          expect(error.url).toBe(targetUrl);
          expect(error.message).toContain(targetUrl);
        }
      }
    });
  });

  describe('retrieval', () => {
    it('should retrieve a bookmark by ID using getById and findById', () => {
      const created = service.create({
        url: 'https://example.com/retrieve',
        title: 'Retrieve Me',
        tags: ['test'],
      });

      const foundGet = service.getById(created.id);
      const foundFind = service.findById(created.id);

      expect(foundGet).toEqual(created);
      expect(foundFind).toEqual(created);
    });

    it('should return undefined when retrieving a non-existent ID', () => {
      const result = service.getById('non-existent-uuid');
      expect(result).toBeUndefined();
    });

    it('should retrieve a bookmark by URL using findByUrl', () => {
      const created = service.create({
        url: 'https://example.com/by-url',
        title: 'By URL',
      });

      const found = service.findByUrl('https://example.com/by-url');
      expect(found).toEqual(created);
    });

    it('should return undefined when finding by a non-existent URL', () => {
      const result = service.findByUrl('https://example.com/not-found');
      expect(result).toBeUndefined();
    });

    it('should retrieve all bookmarks sorted by createdAt descending', () => {
      const b1 = service.create({ url: 'https://example.com/first' });
      const b2 = service.create({ url: 'https://example.com/second' });

      const all = service.getAll();
      expect(all.length).toBe(2);
      expect(all[0]?.id).toBe(b2.id);
      expect(all[1]?.id).toBe(b1.id);
    });

    it('should clear all bookmarks when clear() is called', () => {
      service.create({ url: 'https://example.com/1' });
      service.create({ url: 'https://example.com/2' });

      expect(service.getAll().length).toBe(2);

      service.clear();

      expect(service.getAll().length).toBe(0);
      expect(service.findByUrl('https://example.com/1')).toBeUndefined();
    });
  });
});

