import { describe, it, expect, beforeEach } from 'vitest';
import request from 'supertest';
import { app } from '../src/app.js';
import { bookmarkService } from '../src/services/bookmark-service.js';

interface BookmarkResponse {
  id: string;
  url: string;
  title?: string;
  tags: string[];
  createdAt: string;
}

function isBookmarkResponse(data: unknown): data is BookmarkResponse {
  if (typeof data !== 'object' || data === null) return false;
  const item = data as Record<string, unknown>;
  return (
    typeof item.id === 'string' &&
    typeof item.url === 'string' &&
    Array.isArray(item.tags) &&
    typeof item.createdAt === 'string'
  );
}

function isBookmarkResponseArray(data: unknown): data is BookmarkResponse[] {
  return Array.isArray(data) && data.every(isBookmarkResponse);
}

describe('Bookmarks API Integration Tests', () => {
  beforeEach(() => {
    bookmarkService.clear();
  });

  describe('POST /api/v1/bookmarks', () => {
    it('should create a bookmark and return 201 Created with full payload', async () => {
      const payload = {
        url: 'https://example.com/integration-post',
        title: 'Integration Test Bookmark',
        tags: ['integration', 'test'],
      };

      const res = await request(app)
        .post('/api/v1/bookmarks')
        .send(payload)
        .set('Content-Type', 'application/json');

      expect(res.status).toBe(201);
      expect(isBookmarkResponse(res.body)).toBe(true);

      if (isBookmarkResponse(res.body)) {
        expect(res.body.id).toBeDefined();
        expect(res.body.url).toBe(payload.url);
        expect(res.body.title).toBe(payload.title);
        expect(res.body.tags).toEqual(payload.tags);
        expect(res.body.createdAt).toBeDefined();
      }
    });

    it('should create a bookmark with minimal fields and default tags', async () => {
      const payload = {
        url: 'https://example.com/minimal',
      };

      const res = await request(app)
        .post('/api/v1/bookmarks')
        .send(payload);

      expect(res.status).toBe(201);
      expect(isBookmarkResponse(res.body)).toBe(true);

      if (isBookmarkResponse(res.body)) {
        expect(res.body.url).toBe(payload.url);
        expect(res.body.title).toBeUndefined();
        expect(res.body.tags).toEqual([]);
      }
    });
  });

  describe('GET /api/v1/bookmarks', () => {
    it('should return 200 OK and an empty list when no bookmarks exist', async () => {
      const res = await request(app).get('/api/v1/bookmarks');

      expect(res.status).toBe(200);
      expect(isBookmarkResponseArray(res.body)).toBe(true);
      if (isBookmarkResponseArray(res.body)) {
        expect(res.body).toEqual([]);
      }
    });

    it('should return 200 OK and all bookmarks sorted by createdAt descending', async () => {
      const res1 = await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://example.com/first', title: 'First' });

      await new Promise((resolve) => setTimeout(resolve, 10));

      const res2 = await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://example.com/second', title: 'Second' });

      const resList = await request(app).get('/api/v1/bookmarks');

      expect(resList.status).toBe(200);
      expect(isBookmarkResponseArray(resList.body)).toBe(true);

      if (isBookmarkResponseArray(resList.body) && isBookmarkResponse(res1.body) && isBookmarkResponse(res2.body)) {
        expect(resList.body.length).toBe(2);
        expect(resList.body[0]?.id).toBe(res2.body.id);
        expect(resList.body[1]?.id).toBe(res1.body.id);
      }
    });
  });

  describe('GET /api/v1/bookmarks/:id', () => {
    it('should return 200 OK and the bookmark by ID', async () => {
      const createdRes = await request(app)
        .post('/api/v1/bookmarks')
        .send({
          url: 'https://example.com/single',
          title: 'Single Item',
          tags: ['single'],
        });

      expect(isBookmarkResponse(createdRes.body)).toBe(true);
      if (!isBookmarkResponse(createdRes.body)) return;

      const bookmarkId = createdRes.body.id;
      const getRes = await request(app).get(`/api/v1/bookmarks/${bookmarkId}`);

      expect(getRes.status).toBe(200);
      expect(isBookmarkResponse(getRes.body)).toBe(true);
      if (isBookmarkResponse(getRes.body)) {
        expect(getRes.body.id).toBe(bookmarkId);
        expect(getRes.body.url).toBe('https://example.com/single');
        expect(getRes.body.title).toBe('Single Item');
        expect(getRes.body.tags).toEqual(['single']);
      }
    });
  });

  describe('DELETE /api/v1/bookmarks/:id', () => {
    it('should return 204 No Content when deleting an existing bookmark and 404 subsequently', async () => {
      const createdRes = await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://example.com/delete-target' });

      expect(isBookmarkResponse(createdRes.body)).toBe(true);
      if (!isBookmarkResponse(createdRes.body)) return;

      const bookmarkId = createdRes.body.id;

      const deleteRes = await request(app).delete(`/api/v1/bookmarks/${bookmarkId}`);
      expect(deleteRes.status).toBe(204);

      const getRes = await request(app).get(`/api/v1/bookmarks/${bookmarkId}`);
      expect(getRes.status).toBe(404);
    });
  });
});

