edits.newText:
interface PaginationMeta {
  page: number;
  limit: number;
  total: number;
  totalPages: number;
}

interface PaginatedBookmarkResponse {
  data: BookmarkResponse[];
  pagination: PaginationMeta;
}

function isBookmarkResponse(data: unknown): data is BookmarkResponse {
  if (typeof data !== 'object' || data === null) return false;
  const item = data as Record<string, unknown>;
  return (
    typeof item.id === 'string' &&
    typeof item.url === 'string' &&
    Array.isArray(item.tags) &&
    typeof item.createdAt === 'string'
  );
}

function isPaginatedBookmarkResponse(data: unknown): data is PaginatedBookmarkResponse {
  if (typeof data !== 'object' || data === null) return false;
  const obj = data as Record<string, unknown>;
  if (!Array.isArray(obj.data) || !obj.data.every(isBookmarkResponse)) return false;
  if (typeof obj.pagination !== 'object' || obj.pagination === null) return false;
  const p = obj.pagination as Record<string, unknown>;
  return (
    typeof p.page === 'number' &&
    typeof p.limit === 'number' &&
    typeof p.total === 'number' &&
    typeof p.totalPages === 'number'
  );
}

describe('GET /api/v1/bookmarks', () => {
  it('should return 200 OK and an empty list when no bookmarks exist', async () => {
    const res = await request(app).get('/api/v1/bookmarks');

    expect(res.status).toBe(200);
    expect(isPaginatedBookmarkResponse(res.body)).toBe(true);
    if (isPaginatedBookmarkResponse(res.body)) {
      expect(res.body.data).toEqual([]);
      expect(res.body.pagination.total).toBe(0);
      expect(res.body.pagination.page).toBe(1);
      expect(res.body.pagination.limit).toBe(20);
    }
  });

  it('should return 200 OK and all bookmarks sorted by createdAt descending', async () => {
    const res1 = await request(app)
      .post('/api/v1/bookmarks')
      .send({ url: 'https://example.com/first', title: 'First' });

    await new Promise((resolve) => setTimeout(resolve, 10));

    const res2 = await request(app)
      .post('/api/v1/bookmarks')
      .send({ url: 'https://example.com/second', title: 'Second' });

    const resList = await request(app).get('/api/v1/bookmarks?page=1&limit=20');

    expect(resList.status).toBe(200);
    expect(isPaginatedBookmarkResponse(resList.body)).toBe(true);

    if (isPaginatedBookmarkResponse(resList.body) && isBookmarkResponse(res1.body) && isBookmarkResponse(res2.body)) {
      expect(resList.body.data.length).toBe(2);
      expect(resList.body.data[0]?.id).toBe(res2.body.id);
      expect(resList.body.data[1]?.id).toBe(res1.body.id);
      expect(resList.body.pagination.page).toBe(1);
      expect(resList.body.pagination.limit).toBe(20);
      expect(resList.body.pagination.total).toBe(2);
      expect(resList.body.pagination.totalPages).toBe(1);
    }
  });
});

