import { describe, it, expect, beforeEach } from 'vitest';
import request from 'supertest';
import { app } from '../src/app.js';
import { bookmarkService } from '../src/services/bookmark-service.js';

interface PaginationMeta {
  page: number;
  limit: number;
  total: number;
  totalPages: number;
}

interface PaginatedResponse {
  data: Array<{
    id: string;
    url: string;
    title?: string;
    tags: string[];
    createdAt: string;
  }>;
  pagination: PaginationMeta;
}

function isPaginatedResponse(data: unknown): data is PaginatedResponse {
  if (typeof data !== 'object' || data === null) return false;
  const obj = data as Record<string, unknown>;
  if (!Array.isArray(obj.data)) return false;
  if (typeof obj.pagination !== 'object' || obj.pagination === null) return false;
  const p = obj.pagination as Record<string, unknown>;
  return (
    typeof p.page === 'number' &&
    typeof p.limit === 'number' &&
    typeof p.total === 'number' &&
    typeof p.totalPages === 'number'
  );
}

describe('GET /api/v1/bookmarks Pagination', () => {
  beforeEach(() => {
    bookmarkService.clear();
  });

  it('should use default page 1 and limit 20 when no query params are provided', async () => {
    for (let i = 1; i <= 5; i++) {
      bookmarkService.create({ url: `https://example.com/${i}` });
    }

    const res = await request(app).get('/api/v1/bookmarks');
    expect(res.status).toBe(200);
    expect(isPaginatedResponse(res.body)).toBe(true);

    if (isPaginatedResponse(res.body)) {
      expect(res.body.pagination.page).toBe(1);
      expect(res.body.pagination.limit).toBe(20);
      expect(res.body.pagination.total).toBe(5);
      expect(res.body.pagination.totalPages).toBe(1);
      expect(res.body.data.length).toBe(5);
    }
  });

  it('should handle page 0 by defaulting/normalizing to page 1', async () => {
    for (let i = 1; i <= 5; i++) {
      bookmarkService.create({ url: `https://example.com/${i}` });
    }

    const res = await request(app).get('/api/v1/bookmarks?page=0&limit=10');
    expect(res.status).toBe(200);
    expect(isPaginatedResponse(res.body)).toBe(true);

    if (isPaginatedResponse(res.body)) {
      expect(res.body.pagination.page).toBe(1);
      expect(res.body.pagination.limit).toBe(10);
      expect(res.body.data.length).toBe(5);
    }
  });

  it('should handle negative page by normalizing to page 1', async () => {
    for (let i = 1; i <= 3; i++) {
      bookmarkService.create({ url: `https://example.com/${i}` });
    }

    const res = await request(app).get('/api/v1/bookmarks?page=-5&limit=10');
    expect(res.status).toBe(200);
    expect(isPaginatedResponse(res.body)).toBe(true);

    if (isPaginatedResponse(res.body)) {
      expect(res.body.pagination.page).toBe(1);
    }
  });

  it('should handle negative limit by normalizing to limit 1', async () => {
    for (let i = 1; i <= 3; i++) {
      bookmarkService.create({ url: `https://example.com/${i}` });
    }

    const res = await request(app).get('/api/v1/bookmarks?page=1&limit=-10');
    expect(res.status).toBe(200);
    expect(isPaginatedResponse(res.body)).toBe(true);

    if (isPaginatedResponse(res.body)) {
      expect(res.body.pagination.limit).toBe(1);
      expect(res.body.data.length).toBe(1);
      expect(res.body.pagination.total).toBe(3);
      expect(res.body.pagination.totalPages).toBe(3);
    }
  });

  it('should handle limit 0 by normalizing to limit 1', async () => {
    for (let i = 1; i <= 3; i++) {
      bookmarkService.create({ url: `https://example.com/${i}` });
    }

    const res = await request(app).get('/api/v1/bookmarks?page=1&limit=0');
    expect(res.status).toBe(200);
    expect(isPaginatedResponse(res.body)).toBe(true);

    if (isPaginatedResponse(res.body)) {
      expect(res.body.pagination.limit).toBe(1);
      expect(res.body.data.length).toBe(1);
    }
  });

  it('should cap limit > 100 at 100', async () => {
    for (let i = 1; i <= 5; i++) {
      bookmarkService.create({ url: `https://example.com/${i}` });
    }

    const res = await request(app).get('/api/v1/bookmarks?limit=150');
    expect(res.status).toBe(200);
    expect(isPaginatedResponse(res.body)).toBe(true);

    if (isPaginatedResponse(res.body)) {
      expect(res.body.pagination.limit).toBe(100);
      expect(res.body.pagination.total).toBe(5);
    }
  });

  it('should correctly paginate across multiple pages', async () => {
    for (let i = 1; i <= 5; i++) {
      bookmarkService.create({ url: `https://example.com/${i}` });
    }

    const page1Res = await request(app).get('/api/v1/bookmarks?page=1&limit=2');
    expect(page1Res.status).toBe(200);
    expect(isPaginatedResponse(page1Res.body)).toBe(true);

    if (isPaginatedResponse(page1Res.body)) {
      expect(page1Res.body.pagination.page).toBe(1);
      expect(page1Res.body.pagination.limit).toBe(2);
      expect(page1Res.body.pagination.total).toBe(5);
      expect(page1Res.body.pagination.totalPages).toBe(3);
      expect(page1Res.body.data.length).toBe(2);
    }

    const page2Res = await request(app).get('/api/v1/bookmarks?page=2&limit=2');
    expect(page2Res.status).toBe(200);
    expect(isPaginatedResponse(page2Res.body)).toBe(true);

    if (isPaginatedResponse(page2Res.body)) {
      expect(page2Res.body.pagination.page).toBe(2);
      expect(page2Res.body.pagination.limit).toBe(2);
      expect(page2Res.body.data.length).toBe(2);
    }

    const page3Res = await request(app).get('/api/v1/bookmarks?page=3&limit=2');
    expect(page3Res.status).toBe(200);
    expect(isPaginatedResponse(page3Res.body)).toBe(true);

    if (isPaginatedResponse(page3Res.body)) {
      expect(page3Res.body.pagination.page).toBe(3);
      expect(page3Res.body.data.length).toBe(1);
    }
  });

  it('should return empty data array when requesting a page beyond total pages', async () => {
    for (let i = 1; i <= 3; i++) {
      bookmarkService.create({ url: `https://example.com/${i}` });
    }

