import { describe, it, expect, beforeEach } from 'vitest';
import request from 'supertest';
import { app } from '../src/app.js';
import { bookmarkService } from '../src/services/bookmark-service.js';

interface BookmarkResponse {
  id: string;
  url: string;
  title?: string;
  tags: string[];
  createdAt: string;
}

function isBookmarkResponse(data: unknown): data is BookmarkResponse {
  if (typeof data !== 'object' || data === null) return false;
  const item = data as Record<string, unknown>;
  return (
    typeof item.id === 'string' &&
    typeof item.url === 'string' &&
    Array.isArray(item.tags) &&
    typeof item.createdAt === 'string'
  );
}

describe('PATCH /api/v1/bookmarks/:id', () => {
  beforeEach(() => {
    bookmarkService.clear();
  });

  it('should partially update the title only', async () => {
    const created = bookmarkService.create({
      url: 'https://example.com/title-update',
      title: 'Original Title',
      tags: ['initial'],
    });

    const res = await request(app)
      .patch(`/api/v1/bookmarks/${created.id}`)
      .send({ title: 'Updated Title' });

    expect(res.status).toBe(200);
    expect(isBookmarkResponse(res.body)).toBe(true);

    if (isBookmarkResponse(res.body)) {
      expect(res.body.id).toBe(created.id);
      expect(res.body.url).toBe(created.url);
      expect(res.body.title).toBe('Updated Title');
      expect(res.body.tags).toEqual(['initial']);
      expect(res.body.createdAt).toBe(created.createdAt);
    }
  });

  it('should partially update the tags only', async () => {
    const created = bookmarkService.create({
      url: 'https://example.com/tags-update',
      title: 'Title',
      tags: ['old-tag'],
    });

    const res = await request(app)
      .patch(`/api/v1/bookmarks/${created.id}`)
      .send({ tags: ['new-tag-1', 'new-tag-2'] });

    expect(res.status).toBe(200);
    expect(isBookmarkResponse(res.body)).toBe(true);

    if (isBookmarkResponse(res.body)) {
      expect(res.body.id).toBe(created.id);
      expect(res.body.url).toBe(created.url);
      expect(res.body.title).toBe('Title');
      expect(res.body.tags).toEqual(['new-tag-1', 'new-tag-2']);
    }
  });

  it('should update both title and tags simultaneously', async () => {
    const created = bookmarkService.create({
      url: 'https://example.com/both-update',
      title: 'Original',
      tags: ['old'],
    });

    const res = await request(app)
      .patch(`/api/v1/bookmarks/${created.id}`)
      .send({ title: 'New Title', tags: ['updated-tag'] });

    expect(res.status).toBe(200);
    expect(isBookmarkResponse(res.body)).toBe(true);

    if (isBookmarkResponse(res.body)) {
      expect(res.body.title).toBe('New Title');
      expect(res.body.tags).toEqual(['updated-tag']);
    }
  });

  it('should return 404 when attempting to update a non-existent bookmark ID', async () => {
    const res = await request(app)
      .patch('/api/v1/bookmarks/non-existent-id')
      .send({ title: 'Cannot Update' });

    expect(res.status).toBe(404);
    expect(res.body).toEqual({ error: 'Bookmark not found: non-existent-id' });
  });

  it('should reject requests attempting to update the URL with 400 Bad Request', async () => {
    const created = bookmarkService.create({
      url: 'https://example.com/immutable-url',
      title: 'Immutable',
    });

    const res = await request(app)
      .patch(`/api/v1/bookmarks/${created.id}`)
      .send({ url: 'https://example.com/new-url' });

    expect(res.status).toBe(400);
    expect(res.body).toEqual({ error: 'URL is immutable and cannot be updated' });

    // Verify the URL did not change
    const check = bookmarkService.getById(created.id);
    expect(check?.url).toBe('https://example.com/immutable-url');
  });

  it('should reject requests attempting to update the URL even when title is also provided', async () => {
    const created = bookmarkService.create({
      url: 'https://example.com/immutable-url-2',
      title: 'Original',
    });

    const res = await request(app)
      .patch(`/api/v1/bookmarks/${created.id}`)
      .send({ title: 'New Title', url: 'https://example.com/mutated' });

    expect(res.status).toBe(400);
    expect(res.body).toEqual({ error: 'URL is immutable and cannot be updated' });
  });

  it('should return 422 when updating with invalid title exceeding 200 characters', async () => {
    const created = bookmarkService.create({
      url: 'https://example.com/invalid-patch',
    });

    const res = await request(app)
      .patch(`/api/v1/bookmarks/${created.id}`)
      .send({ title: 'a'.repeat(201) });

    expect(res.status).toBe(422);
  });
});

