export const bookmarksRouter = Router();

/**
 * Route handler for creating a new bookmark.
 *
 * @param req - Express request object containing bookmark data in the request body.
 * @param res - Express response object returning 201 with the created bookmark.
 * @param next - Express next middleware function for handling errors.
 * @returns Promise or void resolving when the response has been sent.
 *
 * @example
 * ```http
 * POST /api/v1/bookmarks
 * Content-Type: application/json
 *
 * {
 *   "url": "https://example.com",
 *   "title": "Example Domain",
 *   "tags": ["reference"]
 * }
 * ```
 */
bookmarksRouter.post(
  ['/', '/bookmarks', '/api/v1/bookmarks'],
  (req: Request, res: Response, next: NextFunction) => {
    try {
      const body: unknown = req.body;
      const parseResult = createBookmarkSchema.safeParse(body);

      if (!parseResult.success) {
        return next(parseResult.error);
      }

      const newBookmark = bookmarkService.create(parseResult.data);
      res.status(201).json(newBookmark);
    } catch (err: unknown) {
      next(err);
    }
  }
);

