export interface CreateBookmarkDTO {
  url: string;
  title?: string;
  tags?: string[];
}

export interface UpdateBookmarkDTO {
  title?: string;
  tags?: string[];
}

export interface PaginationMeta {
  page: number;
  limit: number;
  total: number;
  totalPages: number;
}

export interface PaginatedResult<T> {
  data: T[];
  pagination: PaginationMeta;
}

export class DuplicateBookmarkError extends Error {
  constructor(public readonly url: string) {
    super(`Bookmark with URL already exists: ${url}`);
    this.name = 'DuplicateBookmarkError';
  }
}

export class BookmarkNotFoundError extends Error {
  constructor(public readonly id: string) {
    super(`Bookmark not found: ${id}`);
    this.name = 'BookmarkNotFoundError';
  }
}

export class BookmarkService {
  private readonly bookmarks: Map<string, Bookmark> = new Map();

  /**
   * Creates a new bookmark with a generated UUID and timestamp.
   * Throws DuplicateBookmarkError if a bookmark with the same URL already exists.
   */
  create(input: CreateBookmarkDTO): Bookmark {
    if (this.findByUrl(input.url)) {
      throw new DuplicateBookmarkError(input.url);
    }

    const id = randomUUID();
    const createdAt = new Date().toISOString();
    const bookmark: Bookmark = {
      id,
      url: input.url,
      ...(input.title !== undefined ? { title: input.title } : {}),
      tags: input.tags ? [...input.tags] : [],
      createdAt,
    };

    this.bookmarks.set(id, bookmark);
    return bookmark;
  }

  /**
   * Retrieves a bookmark by its UUID.
   */
  getById(id: string): Bookmark | undefined {
    return this.bookmarks.get(id);
  }

  /**
   * Retrieves a bookmark by its UUID (alias for getById).
   */
  findById(id: string): Bookmark | undefined {
    return this.getById(id);
  }

  /**
   * Finds a bookmark by its exact URL.
   */
  findByUrl(url: string): Bookmark | undefined {
    for (const bookmark of this.bookmarks.values()) {
      if (bookmark.url === url) {
        return bookmark;
      }
    }
    return undefined;
  }

  /**
   * Retrieves all bookmarks sorted by createdAt descending.
   */
  getAll(): Bookmark[] {
    return Array.from(this.bookmarks.values()).sort(
      (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    );
  }

  /**
   * Retrieves a paginated list of bookmarks sorted by createdAt descending.
   */
  getPaginated(page = 1, limit = 20): PaginatedResult<Bookmark> {
    const validPage = Math.max(1, Math.floor(page) || 1);
    const validLimit = Math.min(100, Math.max(1, Math.floor(limit) || 1));

    const all = this.getAll();
    const total = all.length;
    const totalPages = Math.ceil(total / validLimit);
    const offset = (validPage - 1) * validLimit;
    const data = all.slice(offset, offset + validLimit);

    return {
      data,
      pagination: {
        page: validPage,
        limit: validLimit,
        total,
        totalPages,
      },
    };
  }

  /**
   * Updates the title and/or tags of an existing bookmark. URL cannot be changed.
   * Returns the updated bookmark if found, or undefined if not found.
   */
  update(id: string, data: UpdateBookmarkDTO): Bookmark | undefined {
    const existing = this.bookmarks.get(id);
    if (!existing) {
      return undefined;
    }

    const updated: Bookmark = {
      ...existing,
      title: data.title !== undefined ? data.title : existing.title,
      tags: data.tags !== undefined ? [...data.tags] : existing.tags,
    };

    this.bookmarks.set(id, updated);
    return updated;
  }

  /**
   * Deletes a bookmark by its UUID.
   * Returns true if deleted, or false if not found.
   */
  delete(id: string): boolean {
    return this.bookmarks.delete(id);
  }

  /**
   * Clears all bookmarks from memory (useful for testing).
   */
  clear(): void {
    this.bookmarks.clear();
  }
}

export const bookmarkService = new BookmarkService();
export default bookmarkService;

import { Router, type Request, type Response, type NextFunction } from 'express';
import { z } from 'zod';
import { bookmarkService } from '../services/bookmark-service.js';

export const createBookmarkSchema = z.object({
  url: z.string().url().max(2048),
  title: z.string().max(200).optional(),
  tags: z.array(z.string().max(50)).max(10).optional(),
});

export type CreateBookmarkInput = z.infer<typeof createBookmarkSchema>;

export const updateBookmarkSchema = z.object({
  title: z.string().max(200).optional(),
  tags: z.array(z.string().max(50)).max(10).optional(),
});

export type UpdateBookmarkInput = z.infer<typeof updateBookmarkSchema>;

function parseQueryInt(val: unknown, fallback: number): number {
  if (typeof val === 'string') {
    const parsed = parseInt(val, 10);
    if (!Number.isNaN(parsed)) {
      return parsed;
    }
  }
  return fallback;
}

export const bookmarksRouter = Router();

bookmarksRouter.get('/', (req: Request, res: Response) => {
  const page = parseQueryInt(req.query.page, 1);
  const limit = parseQueryInt(req.query.limit, 20);

  const result = bookmarkService.getPaginated(page, limit);
  res.status(200).json(result);
});

bookmarksRouter.post('/', (req: Request, res: Response, next: NextFunction) => {
  try {
    const body: unknown = req.body;
    const parseResult = createBookmarkSchema.safeParse(body);

    if (!parseResult.success) {
      return next(parseResult.error);
    }

    const bookmark = bookmarkService.create(parseResult.data);
    res.status(201).json(bookmark);
  } catch (error: unknown) {
    next(error);
  }
});

bookmarksRouter.get('/:id', (req: Request<{ id: string }>, res: Response) => {
  const { id } = req.params;
  const bookmark = bookmarkService.getById(id);
  if (!bookmark) {
    res.status(404).json({ error: `Bookmark not found: ${id}` });
    return;
  }
  res.status(200).json(bookmark);
});

bookmarksRouter.patch('/:id', (req: Request<{ id: string }>, res: Response, next: NextFunction) => {
  const { id } = req.params;

  const body: unknown = req.body;
  if (typeof body === 'object' && body !== null && 'url' in body && (body as Record<string, unknown>).url !== undefined) {
    res.status(400).json({ error: 'URL is immutable and cannot be updated' });
    return;
  }

  const parseResult = updateBookmarkSchema.safeParse(body);
  if (!parseResult.success) {
    return next(parseResult.error);
  }

  const updated = bookmarkService.update(id, parseResult.data);
  if (!updated) {
    res.status(404).json({ error: `Bookmark not found: ${id}` });
    return;
  }

  res.status(200).json(updated);
});

bookmarksRouter.delete('/:id', (req: Request<{ id: string }>, res: Response) => {
  const { id } = req.params;
  const deleted = bookmarkService.delete(id);
  if (!deleted) {
    res.status(404).json({ error: `Bookmark not found: ${id}` });
    return;
  }
  res.status(204).send();
});

export default bookmarksRouter;

