        service.create({ url: 'https://example.com' });
      }).toThrow(DuplicateBookmarkError);
    });

    it('should include the conflicting URL in the DuplicateBookmarkError message', () => {
      const targetUrl = 'https://example.com/duplicate';
      service.create({ url: targetUrl });

      try {
        service.create({ url: targetUrl });
        expect.unreachable('Should have thrown DuplicateBookmarkError');
      } catch (error: unknown) {
        expect(error instanceof DuplicateBookmarkError).toBe(true);
        if (error instanceof DuplicateBookmarkError) {
          expect(error.url).toBe(targetUrl);
          expect(error.message).toContain(targetUrl);
        }
      }
    });
  });

