export const bookmarksRouter = Router();

/**
 * Route handler for GET /api/v1/bookmarks.
 * Retrieves a paginated list of bookmarks sorted by creation date descending.
 *
 * @param req - Express request with optional `page` and `limit` query parameters.
 * @param res - Express response returning paginated bookmarks.
 * @returns void
 *
 * @example
 * // GET /api/v1/bookmarks?page=1&limit=20
 * // Response (200 OK):
 * // {
 * //   "data": [{ "id": "...", "url": "https://example.com", "tags": [], "createdAt": "..." }],
 * //   "pagination": { "page": 1, "limit": 20, "total": 1, "totalPages": 1 }
 * // }
 */
bookmarksRouter.get('/', (req: Request, res: Response) => {
  const page = parseQueryInt(req.query.page, 1);
  const limit = parseQueryInt(req.query.limit, 20);

  const result = bookmarkService.getPaginated(page, limit);
  res.status(200).json(result);
});

/**
 * Route handler for POST /api/v1/bookmarks.
 * Validates the request body against `createBookmarkSchema` and creates a new bookmark.
 *
 * @param req - Express request containing the bookmark payload in the body.
 * @param res - Express response returning the created bookmark with status 201.
 * @param next - Express next function for forwarding errors to centralized error handling.
 * @returns void
 *
 * @example
 * // POST /api/v1/bookmarks
 * // Headers: Content-Type: application/json
 * // Body: { "url": "https://example.com", "title": "Example", "tags": ["docs"] }
 * // Response (201 Created):
 * // { "id": "...", "url": "https://example.com", "title": "Example", "tags": ["docs"], "createdAt": "..." }
 */
bookmarksRouter.post('/', (req: Request, res: Response, next: NextFunction) => {
  try {
    const body: unknown = req.body;
    const parseResult = createBookmarkSchema.safeParse(body);

    if (!parseResult.success) {
      return next(parseResult.error);
    }

    const bookmark = bookmarkService.create(parseResult.data);
    res.status(201).json(bookmark);
  } catch (error: unknown) {
    next(error);
  }
});

/**
 * Route handler for GET /api/v1/bookmarks/search.
 * Searches bookmarks by title (case-insensitive substring) and tags (case-insensitive exact match).
 *
 * @param req - Express request containing the required `q` query string parameter.
 * @param res - Express response returning an array of matching bookmarks with status 200 or 400 Bad Request.
 * @returns void
 *
 * @example
 * // GET /api/v1/bookmarks/search?q=typescript
 * // Response (200 OK):
 * // [{ "id": "...", "url": "https://example.com", "title": "TypeScript Handbook", "tags": [], "createdAt": "..." }]
 */
bookmarksRouter.get('/search', (req: Request, res: Response) => {
  const q = req.query.q;
  if (typeof q !== 'string' || q.trim() === '') {
    res.status(400).json({ error: 'Search query parameter "q" is required and cannot be empty' });
    return;
  }

  const results = bookmarkService.search(q);
  res.status(200).json(results);
});

/**
 * Route handler for GET /api/v1/bookmarks/:id.
 * Retrieves a single bookmark by its UUID.
 *
 * @param req - Express request containing the bookmark `id` route parameter.
 * @param res - Express response returning the bookmark with status 200 or 404 Not Found.
 * @returns void
 *
 * @example
 * // GET /api/v1/bookmarks/123e4567-e89b-12d3-a456-426614174000
 * // Response (200 OK):
 * // { "id": "123e4567-...", "url": "https://example.com", "title": "Example", "tags": [], "createdAt": "..." }
 */
bookmarksRouter.get('/:id', (req: Request<{ id: string }>, res: Response) => {
  const { id } = req.params;
  const bookmark = bookmarkService.getById(id);
  if (!bookmark) {
    res.status(404).json({ error: `Bookmark not found: ${id}` });
    return;
  }
  res.status(200).json(bookmark);
});

