 * @param fallback - The fallback integer if parsing fails.
 * @returns The parsed integer or the fallback value.
 *
 * @example
 * ```ts
 * const page = parseQueryInt('2', 1); // returns 2
 * const fallback = parseQueryInt('abc', 1); // returns 1
 * ```
 */
function parseQueryInt(val: unknown, fallback: number): number {
  if (typeof val === 'string') {
    const parsed = parseInt(val, 10);
    if (!Number.isNaN(parsed)) {
      return parsed;
    }
  }
  return fallback;
}

export const bookmarksRouter = Router();

/**
