import { type Request, type Response, type NextFunction } from 'express';
import { ZodError } from 'zod';
import { DuplicateBookmarkError, BookmarkNotFoundError } from '../services/bookmark-service.js';

interface HttpErrorLike {
  status?: number;
  statusCode?: number;
  type?: string;
}

function isHttpError(err: unknown): err is HttpErrorLike {
  return typeof err === 'object' && err !== null && ('status' in err || 'statusCode' in err || 'type' in err);
}

function isInvalidJsonError(err: unknown): boolean {
  if (err instanceof SyntaxError) {
    if (isHttpError(err)) {
      if (err.status === 400 || err.statusCode === 400 || err.type === 'entity.parse.failed') {
        return true;
      }
    }
  }
  return false;
}

export function errorHandler(
  err: unknown,
  _req: Request,
  res: Response,
  _next: NextFunction
): void {
  // 1. Invalid JSON body
  if (isInvalidJsonError(err)) {
    res.status(400).json({ error: 'Invalid JSON' });
    return;
  }

  // 2. Zod validation errors
  if (err instanceof ZodError) {
    res.status(422).json({
      error: 'Validation failed',
      details: err.issues,
    });
    return;
  }

  // 3. Known domain errors
  if (err instanceof DuplicateBookmarkError) {
    res.status(409).json({ error: err.message });
    return;
  }

  if (err instanceof BookmarkNotFoundError) {
    res.status(404).json({ error: err.message });
    return;
  }

  // 4. Unexpected errors - 500 with no stack trace
  res.status(500).json({ error: 'Internal server error' });
}

export default errorHandler;

import type { Request, Response, NextFunction } from 'express';

export interface RequestLog {
  method: string;
  path: string;
  status: number;
  duration_ms: number;
}

export function requestLogger(
  req: Request,
  res: Response,
  next: NextFunction
): void {
  const start = Date.now();
  const path =
    typeof req.originalUrl === 'string' && req.originalUrl.length > 0
      ? req.originalUrl.split('?')[0]
      : (req.path ?? '');
  const method = req.method;

  res.on('finish', () => {
    const duration_ms = Date.now() - start;
    const log: RequestLog = {
      method,
      path: path ?? '',
      status: res.statusCode,
      duration_ms,
    };
    console.log(JSON.stringify(log));
  });

  next();
}
